    await repo.patchEvaluation(runId, key, { ...delta, status: to });
    await repo.patchRun(runId, {
      funnelIncrements: { [to === "submitted" ? "submitted" : "failed"]: 1 },
    });
    logger.info("application_submitted_simulated", {
